use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < ks.len() as int {
        if ks[i as usize] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(ks.clone(), k)
            if i >= 0 {
                ks.remove(i as usize)
                vs.remove(i as usize)
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let last = ks.len() - 1
                let ek = ks[last]
                ks.remove(last)
                vs.remove(last)
                println("evict {}", ek)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(ks.clone(), k)
            if i < 0 {
                println("-1")
            } else {
                let v = vs[i as usize]
                ks.remove(i as usize)
                vs.remove(i as usize)
                ks.insert(0, k)
                vs.insert(0, v)
                println("{}", v)
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut j = 0
                while j < ks.len() {
                    if j > 0 {
                        out = out + " "
                    }
                    out = out + ks[j].to_string()
                    j += 1
                }
                println("{}", out)
            }
        }
    }
}

